(window.CARDS = window.CARDS || {}).animal = [{"name":"Лев","emoji":"🦁","meta":["млекопитающее","саванны Африки","самцы до 250 кг"],"description":"Единственная кошка, живущая большими семейными группами — прайдами, где охотой чаще занимаются львицы. Густая грива самца — признак силы и статуса, а её оттенок темнеет с возрастом. Лев издавна считается символом власти и смелости во многих культурах.","fact":"Рёв льва слышен на расстоянии до восьми километров и служит для охраны территории прайда.","wiki_en":"Lion"},{"name":"Тигр","emoji":"🐅","meta":["млекопитающее","леса и джунгли Азии","крупнейшая кошка"],"description":"Самая крупная из диких кошек, отличается характерным рисунком полос, уникальным для каждой особи, как отпечаток пальца. В отличие от многих кошачьих тигр прекрасно плавает и любит воду. Большинство подвидов сегодня находятся под угрозой исчезновения.","fact":"Полосы тигра есть не только на шерсти, но и на коже — рисунок сохраняется даже после бритья.","wiki_en":"Tiger"},{"name":"Леопард","emoji":"🐆","meta":["млекопитающее","Африка и Азия","до 90 кг"],"description":"Скрытный и невероятно сильный хищник, способный затащить добычу вдвое тяжелее себя на дерево, спасая её от гиен и львов. Пятнистая шкура — идеальный камуфляж в саванне и лесу. Леопард — самый широко распространённый из крупных кошачьих в мире.","fact":"Чёрная пантера — не отдельный вид, а леопард или ягуар с редкой тёмной окраской шерсти.","wiki_en":"Leopard"},{"name":"Гепард","emoji":"💨","meta":["млекопитающее","саванны Африки","самое быстрое наземное животное"],"description":"Самое быстрое сухопутное животное планеты — на короткой дистанции разгоняется почти до скорости спортивного автомобиля. В отличие от других крупных кошек не может полностью втягивать когти, что даёт дополнительное сцепление при беге. Чёрные полосы под глазами защищают от солнца, как козырёк.","fact":"Рычать гепард не умеет: вместо этого он мурлычет и издаёт птичий щебет, которым подзывает детёнышей.","wiki_en":"Cheetah"},{"name":"Ягуар","emoji":"🐆","meta":["млекопитающее","леса Южной Америки","самая мощная кошка Америки"],"description":"Крупнейшая кошка Западного полушария с одним из самых мощных укусов среди хищников — способна прокусывать панцири черепах. Часто охотится у воды и отлично плавает, в отличие от многих других кошачьих. У майя и ацтеков ягуар почитался как священное животное.","fact":"В отличие от большинства кошек ягуар нередко убивает добычу укусом прямо в череп.","wiki_en":"Jaguar"},{"name":"Снежный барс","emoji":"❄️","meta":["млекопитающее","горы Центральной Азии","длинный хвост для баланса"],"description":"Обитает высоко в горах Центральной Азии, где густой мех и широкие лапы помогают переносить холод и передвигаться по снегу. Исключительно длинный пушистый хвост служит балансиром на скалах и тёплым укрытием во время сна. Из-за скрытности снежного барса называют призраком гор.","fact":"Снежный барс не умеет рычать, как лев или тигр, — вместо этого он мяукает и шипит.","wiki_en":"Snow leopard"},{"name":"Рысь","emoji":"🐈","meta":["млекопитающее","леса Евразии и Северной Америки","кисточки на ушах"],"description":"Лесная кошка с характерными кисточками на ушах и пушистыми «бакенбардами», которые помогают улавливать звуки и направление ветра. Широкие лапы работают как снегоступы, позволяя бесшумно подкрадываться к добыче по глубокому снегу. Охотится в основном в одиночку, предпочитая засаду погоне.","fact":"Кисточки на ушах рыси, предположительно, помогают точнее улавливать звуки в лесу.","wiki_en":"Lynx"},{"name":"Африканский слон","emoji":"🐘","meta":["млекопитающее","саванны и леса Африки","крупнейшее наземное животное"],"description":"Самое крупное ныне живущее наземное животное с огромными ушами, которые помогают охлаждать тело в жаркой саванне. Хобот содержит десятки тысяч мышц и служит и для еды, и для питья, и для общения. Слоны живут сложными семейными группами во главе со старшей самкой.","fact":"И самцы, и самки африканского слона обычно имеют бивни, в отличие от азиатских слонов.","wiki_en":"African elephant"},{"name":"Жираф","emoji":"🦒","meta":["млекопитающее","саванны Африки","самое высокое животное"],"description":"Самое высокое наземное животное планеты, чья длинная шея при этом состоит всего из семи позвонков — столько же, сколько у человека. Пятнистый узор шерсти уникален для каждой особи, как отпечаток пальца. Жирафы спят очень мало, часто урывками, стоя на ногах.","fact":"У жирафа один из самых длинных языков среди млекопитающих — тёмно-синего цвета, защищающего от солнечных ожогов.","wiki_en":"Giraffe"},{"name":"Зебра","emoji":"🦓","meta":["млекопитающее","равнины Африки","чёрно-белые полосы"],"description":"Африканское непарнокопытное с неповторимым полосатым узором — у каждой зебры он свой, как отпечаток пальца у человека. Полосы, предположительно, сбивают с толку кровососущих насекомых и хищников. Зебры держатся стадами и в дикой природе так и не были по-настоящему одомашнены.","fact":"Точное назначение полос зебры до сих пор обсуждается учёными: одна из версий — защита от укусов мух.","wiki_en":"Zebra"},{"name":"Бегемот","emoji":"🦛","meta":["млекопитающее","реки и озёра Африки","одно из самых опасных животных"],"description":"Полуводное млекопитающее, проводящее день почти целиком в воде, а ночью выходящее пастись на сушу. Несмотря на грузное тело, бегемот отлично бегает на короткие дистанции и очень агрессивно защищает территорию. Его кожа выделяет розоватую слизь, защищающую от солнца и инфекций.","fact":"Бегемоты считаются одними из самых опасных для человека крупных животных Африки.","wiki_en":"Hippopotamus"},{"name":"Носорог","emoji":"🦏","meta":["млекопитающее","Африка и Азия","массивный рог из кератина"],"description":"Крупное толстокожее животное с одним или двумя рогами на морде, состоящими из кератина — того же белка, что и человеческие ногти и волосы. Из-за браконьерской охоты за рогами несколько видов носорогов находятся на грани исчезновения. Зрение у носорога слабое, зато отличные слух и обоняние.","fact":"Рог носорога — плотно спрессованный кератин, и, в отличие от рогов быков, у него нет костной основы.","wiki_en":"Rhinoceros"},{"name":"Горилла","emoji":"🦍","meta":["млекопитающее","леса Центральной Африки","крупнейший примат"],"description":"Крупнейший из ныне живущих приматов, при этом преимущественно травоядный и на удивление спокойный по характеру. Группу горилл обычно возглавляет взрослый самец с серебристой спиной, давший название термину «серебристая спина». Гориллы способны выучить элементы языка жестов для общения с людьми.","fact":"Несмотря на устрашающий вид, горилла питается в основном листьями, стеблями и фруктами.","wiki_en":"Gorilla"},{"name":"Шимпанзе","emoji":"🐵","meta":["млекопитающее","леса Центральной и Западной Африки","родственник человека"],"description":"Один из ближайших ныне живущих родственников человека, с которым мы разделяем подавляющее большинство генома. Шимпанзе используют простые орудия — палки и камни — для добычи еды и передают эти навыки другим особям. Живут сложными социальными группами со своей иерархией.","fact":"Шимпанзе — один из немногих видов животных, способных узнавать себя в зеркале.","wiki_en":"Chimpanzee"},{"name":"Орангутан","emoji":"🦧","meta":["млекопитающее","леса Борнео и Суматры","рыжая шерсть"],"description":"Крупная рыжая человекообразная обезьяна, почти всю жизнь проводящая на деревьях дождевых лесов Юго-Восточной Азии. Название «орангутан» с малайского переводится как «лесной человек». Это один из самых медленно размножающихся приматов, что делает вид особенно уязвимым.","fact":"Слово «орангутан» происходит от малайских слов «оранг» — человек и «утан» — лес.","wiki_en":"Orangutan"},{"name":"Кошачий лемур","emoji":"🐒","meta":["млекопитающее","остров Мадагаскар","длинный полосатый хвост"],"description":"Один из самых узнаваемых лемуров Мадагаскара благодаря длинному чёрно-белому полосатому хвосту, которым он не цепляется за ветки. Активен днём и, в отличие от большинства лемуров, много времени проводит на земле. Живёт группами, где часто главенствуют самки.","fact":"Кошачьи лемуры любят греться на солнце, усаживаясь столбиком и подставляя живот лучам.","wiki_en":"Ring-tailed lemur"},{"name":"Большая панда","emoji":"🐼","meta":["млекопитающее","горные леса Китая","питается в основном бамбуком"],"description":"Медведь, чей рацион почти целиком состоит из бамбука, хотя пищеварительная система у него, как у хищника. Чтобы получать достаточно энергии, панда вынуждена есть многие часы подряд ежедневно. Большая панда — символ Китая и один из самых узнаваемых видов в охране природы.","fact":"У большой панды есть подобие «шестого пальца» — костный отросток запястья, помогающий удерживать стебли бамбука.","wiki_en":"Giant panda"},{"name":"Красная панда","emoji":"🍃","meta":["млекопитающее","горные леса Гималаев","рыжий мех и пушистый хвост"],"description":"Небольшой рыжий зверь с пушистым полосатым хвостом, обитающий в горных лесах Гималаев и Юго-Западного Китая. Несмотря на схожее название, красная панда — не близкий родственник большой панды, а представитель отдельного семейства. Как и её тёзка, питается в основном побегами бамбука.","fact":"Долгое время красную панду относили то к енотовым, то к медвежьим, пока не выделили в собственное семейство.","wiki_en":"Red panda"},{"name":"Коала","emoji":"🐨","meta":["млекопитающее","эвкалиптовые леса Австралии","сумчатое"],"description":"Сумчатое животное, почти всю жизнь проводящее на эвкалиптах, листьями которых практически исключительно питается. Эвкалипт токсичен и малопитателен, поэтому коала спит большую часть суток, экономя энергию. Детёныш коалы донашивается в сумке матери, как и у других сумчатых.","fact":"Коала способна распознавать съедобные эвкалипты по запаху, избегая деревьев с повышенным содержанием токсинов.","wiki_en":"Koala"},{"name":"Кенгуру","emoji":"🦘","meta":["млекопитающее","равнины Австралии","передвигается прыжками"],"description":"Крупное сумчатое, передвигающееся мощными прыжками при помощи сильных задних лап и толстого хвоста, служащего опорой и балансиром. Детёныш кенгуру рождается совсем крошечным и донашивается в сумке матери несколько месяцев. Кенгуру — один из главных символов Австралии.","fact":"Пятиться назад кенгуру почти не способен: строение мощных задних ног и тяжёлого хвоста не позволяет ему отступать.","wiki_en":"Kangaroo"},{"name":"Утконос","emoji":"🦆","meta":["млекопитающее","реки Австралии","откладывает яйца"],"description":"Одно из немногих яйцекладущих млекопитающих на Земле — самка откладывает яйца, а после вылупления выкармливает детёнышей молоком. У утконоса плоский клюв, похожий на утиный, перепончатые лапы и ядовитая шпора на задней лапе у самцов. Обитает в реках и ручьях Восточной Австралии.","fact":"Под водой утконос охотится с закрытыми глазами, находя добычу по слабым электрическим сигналам её мышц.","wiki_en":"Platypus"},{"name":"Вомбат","emoji":"🐾","meta":["млекопитающее","леса и степи Австралии","роет глубокие норы"],"description":"Коренастое сумчатое, проводящее большую часть жизни в разветвлённых подземных норах, которые роет мощными когтистыми лапами. Сумка у самки вомбата открывается назад, чтобы земля не попадала на детёныша во время рытья. Помёт вомбата имеет характерную кубическую форму.","fact":"Кубическая форма помёта помогает вомбату метить территорию: такие «кирпичики» не скатываются с камней и брёвен.","wiki_en":"Wombat"},{"name":"Тасманийский дьявол","emoji":"😈","meta":["млекопитающее","остров Тасмания","крупнейший хищный сумчатый"],"description":"Крупнейший из ныне живущих хищных сумчатых, получивший имя за пронзительные крики и агрессивное поведение во время кормёжки. Обитает исключительно на острове Тасмания после исчезновения на материковой Австралии. Популяция вида серьёзно пострадала от заразной лицевой опухолевой болезни.","fact":"Своё название тасманийский дьявол получил у европейских поселенцев за жуткие ночные крики и рычание.","wiki_en":"Tasmanian devil"},{"name":"Ленивец","emoji":"🦥","meta":["млекопитающее","тропические леса Южной Америки","самое медленное млекопитающее"],"description":"Медлительное древесное млекопитающее, большую часть жизни проводящее вниз головой, вцепившись длинными когтями в ветки. Медленный обмен веществ помогает экономить энергию при скудном листовом рационе. В шерсти ленивца часто селятся водоросли, придающие ей зеленоватый оттенок.","fact":"Из-за медленного метаболизма ленивец спускается на землю по нужде в среднем лишь раз в неделю.","wiki_en":"Sloth"},{"name":"Капибара","emoji":"🐹","meta":["млекопитающее","водоёмы Южной Америки","крупнейший грызун в мире"],"description":"Крупнейший грызун планеты, внешне напоминающий гигантскую морскую свинку, тесно связанную жизнью с водоёмами. Капибара отлично плавает и может подолгу оставаться под водой, спасаясь от хищников. Живёт группами и славится удивительно спокойным, дружелюбным нравом.","fact":"Капибары настолько миролюбивы, что на них нередко отдыхают птицы и сидят другие мелкие животные.","wiki_en":"Capybara"},{"name":"Гигантский муравьед","emoji":"🐜","meta":["млекопитающее","саванны и леса Южной Америки","длинная морда без зубов"],"description":"Крупное млекопитающее с вытянутой безубой мордой и длинным липким языком, которым за день может слизать десятки тысяч муравьёв и термитов. Передвигается, опираясь на костяшки передних лап, чтобы не затупить мощные когти. Ходит медленно, но при угрозе способен яростно защищаться.","fact":"Язык гигантского муравьеда может достигать длины около полуметра и выбрасывается десятки раз в минуту.","wiki_en":"Giant anteater"},{"name":"Броненосец","emoji":"🛡️","meta":["млекопитающее","Северная и Южная Америка","панцирь из костных пластин"],"description":"Млекопитающее, тело которого покрыто панцирем из костных пластин, — отсюда и русское название. Некоторые виды при опасности способны сворачиваться в плотный шар, недоступный для зубов хищника. Броненосцы роют норы мощными когтями и в основном питаются насекомыми.","fact":"В плотный шар сворачиваются только трёхпоясные броненосцы — остальным видам строение панциря этого не позволяет.","wiki_en":"Armadillo"},{"name":"Альпака","emoji":"🦙","meta":["млекопитающее","высокогорья Южной Америки","одомашнена ради шерсти"],"description":"Одомашненное животное семейства верблюдовых, которое в Андах разводят прежде всего ради мягкой и тёплой шерсти. В отличие от ламы, альпаку почти не используют как вьючное животное — она мельче и слабее. Шерсть альпаки бывает десятков природных оттенков, от белого до почти чёрного.","fact":"Шерсть альпаки почти не содержит жира-ланолина, поэтому её не нужно долго отмывать перед прядением и она реже вызывает аллергию.","wiki_en":"Alpaca"},{"name":"Верблюд","emoji":"🐪","meta":["млекопитающее","пустыни Африки и Азии","накапливает жир в горбе"],"description":"Крупное копытное, приспособленное к жизни в пустыне: в горбе оно накапливает не воду, а жир, который при необходимости превращается в энергию и влагу. Широкие ступни не проваливаются в песок, а густые ресницы и способность закрывать ноздри защищают от песчаных бурь. Верблюд может подолгу обходиться без воды.","fact":"После долгой жажды верблюд способен выпить за несколько минут более ста литров воды.","wiki_en":"Camel"},{"name":"Бурый медведь","emoji":"🐻","meta":["млекопитающее","леса Евразии и Северной Америки","всеяден"],"description":"Крупный всеядный хищник, рацион которого меняется по сезонам — от ягод и корней до рыбы и падали. Перед зимней спячкой бурый медведь накапливает значительный слой жира, чтобы пережить холода почти без еды. Несмотря на массивное сложение, способен быстро бегать на короткие дистанции.","fact":"На короткой дистанции бурый медведь способен обогнать бегущего человека, несмотря на массивное тело.","wiki_en":"Brown bear"},{"name":"Белый медведь","emoji":"🐻‍❄️","meta":["млекопитающее","арктические льды","крупнейший наземный хищник"],"description":"Крупнейший из наземных хищников планеты, приспособленный к жизни на арктических льдах, где охотится в основном на тюленей. Его шерсть кажется белой, но на самом деле бесцветна и прозрачна, а под ней скрывается чёрная кожа, поглощающая тепло солнца. Отличный пловец, способный подолгу плыть в ледяной воде.","fact":"Обоняние белого медведя настолько острое, что он находит тюленей, скрытых под слоем снега и льда.","wiki_en":"Polar bear"},{"name":"Волк","emoji":"🐺","meta":["млекопитающее","леса и тундра Северного полушария","живёт стаями"],"description":"Предок домашней собаки, живущий сложными семейными стаями со строгой иерархией и разделением ролей на охоте. Волки способны преодолевать десятки километров за ночь в поисках добычи и общаются друг с другом воем, слышным на большом расстоянии. В культуре волк — один из самых мифологизированных зверей.","fact":"Волк и домашняя собака настолько близки генетически, что их гибриды рождаются и способны давать потомство.","wiki_en":"Wolf"},{"name":"Рыжая лисица","emoji":"🦊","meta":["млекопитающее","леса и поля Северного полушария","самая распространённая лисица"],"description":"Самый широко распространённый хищник из семейства псовых, приспособившийся к жизни рядом с человеком — от лесов до окраин крупных городов. Пушистый хвост помогает лисе сохранять равновесие в прыжке и укрывает нос и лапы во время сна на морозе. Отличается острым слухом, различающим движение мелких грызунов под снегом.","fact":"Рыжая лисица находит мышь по шороху под снегом и прыгает точно в цель, пробивая наст головой вперёд.","wiki_en":"Red fox"},{"name":"Фенек","emoji":"🏜️","meta":["млекопитающее","пустыни Северной Африки","самая маленькая лисица"],"description":"Самая маленькая лисица в мире, узнаваемая по непропорционально большим ушам, которые помогают избавляться от лишнего тепла в пустыне и улавливать шорохи добычи под песком. Густой мех на лапах защищает от раскалённого песка. Активен в основном ночью, когда пустынная жара спадает.","fact":"Огромные уши фенька служат природным «кондиционером», отводя избыточное тепло тела в жаркой пустыне.","wiki_en":"Fennec fox"},{"name":"Песец","emoji":"🧊","meta":["млекопитающее","арктическая тундра","меняет окрас по сезону"],"description":"Небольшая лисица тундры, чья шерсть меняет цвет по сезону — зимой становится белоснежной или голубовато-серой, а летом буреет, сливаясь с почвой. Густой мех и короткие лапы, уши и морда помогают сохранять тепло в суровые арктические холода. Песец способен переносить одни из самых низких температур среди хищников.","fact":"Мех песца зимой настолько густой, что позволяет ему переносить морозы значительно ниже минус тридцати.","wiki_en":"Arctic fox"},{"name":"Енот","emoji":"🦝","meta":["млекопитающее","леса Северной Америки","чёрная «маска» на морде"],"description":"Ловкий всеядный зверь с характерной чёрной «маской» вокруг глаз и очень чувствительными передними лапами, которыми он ощупывает и перебирает пищу. Часто «полощет» еду в воде, хотя учёные считают, что дело скорее в тактильном исследовании, а не в мытье. Хорошо приспособился к жизни рядом с человеком, включая города.","fact":"Передние лапы енота настолько чувствительны, что под водой он ощущает предметы точнее, чем на суше.","wiki_en":"Raccoon"},{"name":"Барсук","emoji":"🦡","meta":["млекопитающее","леса и степи Евразии","роет сложные норы-городки"],"description":"Ночной зверь семейства куньих, известный тем, что роет обширные многоярусные норы — городки, которые семьи барсуков используют десятилетиями, постоянно достраивая. Чёрно-белая полосатая морда служит предупреждающей окраской для хищников. Барсук всеяден и запасает жир к зиме, впадая в неглубокий сон.","fact":"Барсучьи норы-городки могут использоваться и расширяться многими поколениями одной семьи десятилетиями.","wiki_en":"European badger"},{"name":"Калан","emoji":"🦦","meta":["млекопитающее","побережье северной части Тихого океана","использует камни как орудия"],"description":"Морская выдра, почти всю жизнь проводящая в воде, включая сон, — калан заворачивается в водоросли, чтобы его не унесло течением. Один из немногих зверей, использующих камни как орудия, — раскалывает ими раковины моллюсков, лёжа на спине. Самый густой мех среди млекопитающих защищает калана от холодной воды.","fact":"У калана самая густая шерсть среди млекопитающих — на одном квадратном сантиметре кожи растут десятки тысяч волосков.","wiki_en":"Sea otter"},{"name":"Бобр","emoji":"🦫","meta":["млекопитающее","реки и озёра Северного полушария","строит плотины"],"description":"Крупный грызун, известный способностью строить плотины и хатки, которые полностью меняют русла рек и создают целые водно-болотные экосистемы. Мощные резцы бобра растут непрерывно и стачиваются об древесину, которой он же и питается зимой. Плоский чешуйчатый хвост служит рулём при плавании и опорой на суше.","fact":"Плотины бобров бывают настолько масштабными, что их видно даже на снимках со спутника.","wiki_en":"Beaver"},{"name":"Ёж","emoji":"🦔","meta":["млекопитающее","леса и сады Евразии и Африки","колючки для защиты"],"description":"Небольшой ночной зверёк, тело которого покрыто несколькими тысячами игл — видоизменённых волос, служащих защитой от хищников. При опасности ёж сворачивается в плотный колючий шар благодаря особым мышцам вдоль спины. Всеяден, питается насекомыми, слизнями и падалью, помогая садоводам бороться с вредителями.","fact":"У ежа может быть до нескольких тысяч игл, каждая из которых со временем сменяется на новую.","wiki_en":"Hedgehog"},{"name":"Белка","emoji":"🐿️","meta":["млекопитающее","леса Евразии и Северной Америки","делает зимние запасы"],"description":"Проворный древесный грызун с пушистым хвостом, который служит рулём при прыжках между ветками и одеялом во время сна. Осенью белка делает множество тайников с орехами и семенами, но забывает часть из них, невольно помогая лесу восстанавливаться. Зимой не впадает в спячку, а лишь снижает активность в сильные морозы.","fact":"С дерева белка спускается головой вниз: её задние лапы разворачиваются назад, и когти цепляются за ствол.","wiki_en":"Squirrel"},{"name":"Лось","emoji":"🦌","meta":["млекопитающее","леса Евразии и Северной Америки","крупнейший из оленевых"],"description":"Крупнейший из ныне живущих представителей оленевых, легко узнаваемый по массивным лопатообразным рогам самцов, которые сбрасываются и отрастают заново каждый год. Длинные ноги позволяют лосю без труда передвигаться по глубокому снегу и болотам. Отлично плавает и может подолгу кормиться, ныряя за водными растениями.","fact":"Траву лось почти не ест: он обрывает побеги, листья и кору с деревьев и кустов, объедая ветки сверху.","wiki_en":"Moose"},{"name":"Северный олень","emoji":"🛷","meta":["млекопитающее","тундра и тайга Северного полушария","рога есть и у самок"],"description":"Единственный вид оленевых, у которого рога носят не только самцы, но и самки. Широкие раздвоенные копыта работают как снегоступы и вёсла при переправе через реки во время сезонных миграций на многие сотни километров. У народов Севера северный олень веками служил главным источником пищи, одежды и транспорта.","fact":"К зиме глаза северных оленей меняют цвет с золотистого на синеватый — так они лучше видят в полярных сумерках.","wiki_en":"Reindeer"},{"name":"Бизон","emoji":"🦬","meta":["млекопитающее","равнины Северной Америки","символ американских прерий"],"description":"Крупнейшее наземное млекопитающее Северной Америки, некогда населявшее прерии десятками миллионов особей, прежде чем оказаться почти истреблённым в XIX веке. Массивная голова и горб из мышц позволяют бизону разгребать снег в поисках травы даже суровой зимой. Сегодня вид восстанавливается благодаря заповедникам и национальным паркам.","fact":"Несмотря на грузное тело, бизон разгоняется примерно до шестидесяти километров в час и легко обгоняет человека.","wiki_en":"Bison"},{"name":"Як","emoji":"🐂","meta":["млекопитающее","высокогорья Центральной Азии","приспособлен к высоте"],"description":"Крупное лохматое копытное, приспособленное к жизни на большой высоте в горах Тибета и соседних регионов, где воздух разрежен и холодно. Густая длинная шерсть и увеличенные лёгкие с сердцем помогают яку переносить недостаток кислорода. Для местных народов як веками служит источником молока, шерсти, мяса и вьючной силы.","fact":"Молоко яка очень жирное, и в Тибете из него делают масло для традиционного солёного чая.","wiki_en":"Yak"},{"name":"Сурикат","emoji":"👀","meta":["млекопитающее","пустыни юга Африки","живёт большими группами"],"description":"Небольшой представитель семейства мангустовых, живущий крупными сплочёнными группами с чёткими ролями — одни добывают еду, другие стоят на страже, высматривая хищников с воздуха и земли. Тёмные круги вокруг глаз работают как естественные солнцезащитные очки. Сурикаты роют разветвлённые норы, служащие укрытием для всей группы.","fact":"Сурикаты не боятся скорпионов и учат детёнышей обращаться с опасной добычей, прежде чем её съесть.","wiki_en":"Meerkat"},{"name":"Пятнистая гиена","emoji":"🦴","meta":["млекопитающее","саванны Африки","мощнейший укус среди хищников"],"description":"Крупный хищник саванны с одним из самых мощных укусов среди млекопитающих, способным дробить крупные кости в поисках костного мозга. Живёт сплочёнными кланами, где главенствуют самки, которые обычно крупнее и агрессивнее самцов. Пятнистые гиены не только падальщики — значительную часть добычи они убивают сами.","fact":"Характерный пронзительный крик пятнистой гиены за схожесть со смехом дал ей прозвище «смеющаяся гиена».","wiki_en":"Spotted hyena"},{"name":"Дикобраз","emoji":"🪡","meta":["млекопитающее","Африка, Азия, Америка","острые защитные иглы"],"description":"Крупный грызун, тело которого покрыто длинными острыми иглами — видоизменёнными волосами, служащими защитой от хищников. При угрозе дикобраз топорщит иглы, стучит хвостом и может пятиться назад, вонзая их в противника. Вопреки распространённому мифу, дикобраз не умеет стрелять иглами на расстояние.","fact":"Иглы дикобраза легко отделяются и остаются в теле нападавшего, а на их месте со временем отрастают новые.","wiki_en":"Porcupine"},{"name":"Морж","emoji":"🦭","meta":["млекопитающее","арктические побережья","длинные бивни"],"description":"Крупное ластоногое, узнаваемое по длинным бивням, которые есть у обоих полов и используются для схваток, обороны и выбирания тела на лёд. Толстый слой подкожного жира защищает моржа от арктического холода, а жёсткие чувствительные усы помогают находить моллюсков на дне. Моржи держатся большими шумными лежбищами.","fact":"Бивни моржа — это сильно удлинённые верхние клыки, которые растут в течение всей жизни животного.","wiki_en":"Walrus"},{"name":"Дельфин афалина","emoji":"🐬","meta":["млекопитающее","тёплые и умеренные моря","один из самых умных обитателей моря"],"description":"Один из самых изученных и социально сложных морских млекопитающих, узнающий себя в зеркале и использующий уникальный «свист-подпись» для обозначения себя среди сородичей. Афалины охотятся и общаются группами, применяя сложные согласованные стратегии загона рыбы. Ориентируются под водой с помощью эхолокации.","fact":"Спит афалина, отключая по очереди только половину мозга, — иначе она перестала бы всплывать за воздухом.","wiki_en":"Common bottlenose dolphin"},{"name":"Косатка","emoji":"🐳","meta":["млекопитающее","океаны по всему миру","вершина морской пищевой цепи"],"description":"Крупнейший представитель семейства дельфиновых и один из главных хищников Мирового океана, охотящийся даже на крупных китов и акул. Живёт устойчивыми семейными группами со своим набором звуков, передающимся из поколения в поколение. Разные популяции косаток специализируются на разной добыче — от рыбы до морских млекопитающих.","fact":"Во многих группах косаток детёныши не покидают мать даже взрослыми и держатся рядом с ней всю жизнь.","wiki_en":"Orca"},{"name":"Синий кит","emoji":"🐋","meta":["млекопитающее","океаны по всему миру","крупнейшее животное на Земле"],"description":"Крупнейшее животное из когда-либо существовавших на Земле, превосходящее по размеру даже самых больших динозавров. Питается преимущественно крилем, процеживая огромные объёмы воды через пластины китового уса. Несмотря на исполинские размеры, синий кит совершенно безобиден для человека.","fact":"Голос синего кита — один из самых громких звуков живой природы: низкий гул разносится под водой на многие километры.","wiki_en":"Blue whale"},{"name":"Горбатый кит","emoji":"🎵","meta":["млекопитающее","океаны по всему миру","известен своими «песнями»"],"description":"Крупный усатый кит, знаменитый сложными и протяжными «песнями», которые самцы поют во время сезона размножения и которые могут распространяться на десятки километров под водой. Отличается длинными, до трети длины тела, грудными плавниками и эффектными прыжками над водой. Совершает одни из самых протяжённых миграций среди млекопитающих.","fact":"Песни горбатых китов одного региона со временем меняются и распространяются на другие популяции, как музыкальная мода.","wiki_en":"Humpback whale"},{"name":"Нарвал","emoji":"🦄","meta":["млекопитающее","арктические воды","длинный винтовой бивень"],"description":"Арктический кит, самцы которого носят длинный винтообразный бивень — на самом деле сильно вытянутый левый зуб, вырастающий из верхней челюсти. Из-за этого «рога» нарвала в Средние века называли морским единорогом, а его бивни продавали как рог легендарного зверя. Держится небольшими группами среди арктических льдов.","fact":"У нарвала нет спинного плавника — под арктическими льдами он только мешал бы всплывать к трещинам за воздухом.","wiki_en":"Narwhal"},{"name":"Белуха","emoji":"🤍","meta":["млекопитающее","арктические и субарктические воды","белая окраска взрослых особей"],"description":"Небольшой кит, взрослые особи которого окрашены в чисто-белый цвет, тогда как детёныши рождаются серыми и светлеют с возрастом. Белуха обладает подвижной шеей — редкость среди китов, — что позволяет ей поворачивать голову в стороны. Издаёт богатый набор звуков, за что её прозвали морской канарейкой.","fact":"На лбу белухи есть подвижная жировая «дыня», форму которой она меняет, направляя звуки эхолокации.","wiki_en":"Beluga whale"},{"name":"Большая белая акула","emoji":"🦈","meta":["рыба (хрящевая)","океаны по всему миру","крупнейшая хищная рыба"],"description":"Крупнейшая хищная рыба в мире, способная улавливать электрические поля живых существ специальными органами чувств на морде. Несмотря на устрашающую репутацию, закреплённую кинематографом, нападения на людей крайне редки и чаще всего случайны. Большая белая акула — один из немногих видов, способных частично поддерживать температуру тела выше окружающей воды.","fact":"Зубы большой белой акулы сменяются всю жизнь: на месте потерянного вырастает новый из запасного ряда.","wiki_en":"Great white shark"},{"name":"Акула-молот","emoji":"🔨","meta":["рыба (хрящевая)","тёплые моря по всему миру","молотообразная форма головы"],"description":"Хищная акула с уплощённой молотообразной головой, на краях которой расположены глаза и ноздри, — это заметно расширяет обзор и улучшает обоняние. Такая форма головы также насыщена электрорецепторами, помогающими находить добычу, зарывшуюся в песок. Часто охотится на скатов, которых умеет прижимать головой ко дну.","fact":"Некоторые молотоголовые акулы собираются в большие стаи, хотя большинство акул держится в одиночку.","wiki_en":"Hammerhead shark"},{"name":"Китовая акула","emoji":"🐳","meta":["рыба (хрящевая)","тёплые моря по всему миру","крупнейшая рыба на Земле"],"description":"Крупнейшая из ныне живущих рыб, несмотря на исполинские размеры совершенно безобидная для человека и питающаяся планктоном и мелкой рыбой. Процеживает огромные объёмы воды через жабры во время неспешного плавания у поверхности. Узор из светлых пятен на коже китовой акулы уникален для каждой особи.","fact":"Узор пятен на коже китовой акулы индивидуален, как отпечаток пальца, и используется учёными для учёта особей.","wiki_en":"Whale shark"},{"name":"Манта","emoji":"🌊","meta":["рыба (хрящевая)","тропические и субтропические моря","крупнейший скат"],"description":"Крупнейший из скатов, использующий широкие треугольные плавники, похожие на крылья, чтобы буквально «летать» под водой. Питается планктоном, направляя его в рот специальными головными лопастями. Манта отличается на удивление крупным для рыб мозгом и сложным поведением.","fact":"В опытах манты необычно реагировали на собственное отражение, и исследователи сочли это возможным признаком самоузнавания.","wiki_en":"Manta ray"},{"name":"Осьминог","emoji":"🐙","meta":["моллюск (головоногий)","моря по всему миру","восемь рук с присосками"],"description":"Головоногий моллюск с восемью гибкими руками, усеянными присосками, каждая из которых частично управляется собственной нервной системой. Осьминог мгновенно меняет цвет и текстуру кожи, маскируясь под окружающую среду, и считается одним из самых умных беспозвоночных. У него три сердца и голубая кровь.","fact":"Осьминог протискивается почти в любую щель, куда пролезет его клюв, — это единственная твёрдая часть его тела.","wiki_en":"Octopus"},{"name":"Морской конёк","emoji":"🐴","meta":["рыба","тропические и умеренные моря","вынашивает потомство самец"],"description":"Необычная рыба с лошадиной формой головы и вертикальным способом плавания, крайне медлительная и полагающаяся на маскировку среди водорослей. У морских коньков потомство вынашивает самец — самка откладывает икру в специальную сумку на его брюхе. Хвост у морского конька хватательный, как у обезьяны, и служит для удержания на кораллах.","fact":"Морской конёк — один из самых медленных пловцов среди рыб: он движется, быстро трепеща небольшим спинным плавником.","wiki_en":"Seahorse"},{"name":"Рыба-клоун","emoji":"🐠","meta":["рыба","рифы Индийского и Тихого океанов","живёт среди актиний"],"description":"Яркая рифовая рыба, живущая в тесном симбиозе с актиниями, чьи жгучие щупальца защищают её от хищников, а сама рыба чистит хозяина и приносит ей пищу. Особая слизь на теле рыбы-клоуна защищает её от жалящих клеток актинии. Все особи рождаются самцами, а самая крупная рыба в группе становится самкой.","fact":"Мальки рыбы-клоуна сначала дрейфуют в открытой воде и лишь потом отыскивают собственную актинию.","wiki_en":"Clownfish"},{"name":"Зелёная морская черепаха","emoji":"🐢","meta":["пресмыкающееся","тропические и субтропические моря","возвращается на родной пляж"],"description":"Крупная морская черепаха, питающаяся преимущественно водорослями и морской травой, что придаёт зеленоватый оттенок её жиру и дало название виду. Самки проплывают тысячи километров, чтобы вернуться откладывать яйца именно на тот пляж, где вылупились сами. Пол детёнышей зависит от температуры песка в гнезде.","fact":"Отдыхая на дне, зелёная черепаха может не подниматься за воздухом по нескольку часов.","wiki_en":"Green sea turtle"},{"name":"Нильский крокодил","emoji":"🐊","meta":["пресмыкающееся","реки и озёра Африки","один из крупнейших крокодилов"],"description":"Один из крупнейших ныне живущих крокодилов, способный часами неподвижно лежать в засаде у воды, поджидая животных на водопое. Обладает одним из самых мощных укусов среди всех живых существ, хотя мышцы, открывающие пасть, при этом очень слабы. Самка нильского крокодила заметно заботится о потомстве, охраняя гнездо и помогая детёнышам выбраться из яиц.","fact":"Вылупившихся детёнышей самка нильского крокодила переносит к воде в пасти, осторожно удерживая их между зубами.","wiki_en":"Nile crocodile"},{"name":"Комодский варан","emoji":"🐉","meta":["пресмыкающееся","острова Индонезии","крупнейшая ящерица в мире"],"description":"Крупнейшая из ныне живущих ящериц, способная в одиночку охотиться на добычу гораздо крупнее себя, включая оленей и буйволов. В слюне комодского варана содержатся токсины, ослабляющие жертву после укуса. Обитает лишь на нескольких индонезийских островах, давших виду название.","fact":"Комодский варан способен учуять запах падали на расстоянии в несколько километров.","wiki_en":"Komodo dragon"},{"name":"Хамелеон","emoji":"🦎","meta":["пресмыкающееся","Африка, Мадагаскар, Южная Европа","меняет окраску"],"description":"Древесная ящерица, знаменитая способностью менять окраску кожи — не столько ради маскировки, сколько для терморегуляции и общения с сородичами. Глаза хамелеона двигаются независимо друг от друга, давая почти круговой обзор. Длинный липкий язык выбрасывается быстрее, чем моргает глаз, чтобы поймать насекомое.","fact":"Цвет хамелеон меняет не пигментами, а перестраивая слой крошечных кристаллов в коже, которые по-разному отражают свет.","wiki_en":"Chameleon"},{"name":"Зелёная игуана","emoji":"🦎","meta":["пресмыкающееся","Центральная и Южная Америка","крупная древесная ящерица"],"description":"Крупная древесная ящерица тропических лесов Америки, несмотря на название способная менять оттенок от ярко-зелёного до буроватого и почти оранжевого. Гребень острых чешуй вдоль спины и длинный хвост помогают защищаться от хищников и удерживать равновесие на ветках. При опасности игуана способна прыгать в воду с большой высоты и хорошо плавать.","fact":"Взрослая зелёная игуана почти полностью растительноядна и питается листьями, цветами и плодами.","wiki_en":"Green iguana"},{"name":"Королевская кобра","emoji":"🐍","meta":["пресмыкающееся","леса Южной и Юго-Восточной Азии","самая длинная ядовитая змея"],"description":"Самая длинная ядовитая змея в мире, при угрозе способная приподнимать переднюю треть тела и раздувать характерный капюшон. В отличие от большинства змей, королевская кобра строит гнездо из листьев для кладки яиц и охраняет его. Питается преимущественно другими змеями, включая ядовитых.","fact":"К настоящим кобрам королевская кобра не относится: её выделяют в отдельный род с названием «пожиратель змей».","wiki_en":"King cobra"},{"name":"Анаконда","emoji":"🐍","meta":["пресмыкающееся","реки и болота Южной Америки","одна из крупнейших змей мира"],"description":"Одна из самых тяжёлых змей в мире, большую часть жизни проводящая в воде рек и болот, где легче удерживать массивное тело. Анаконда — удав, поэтому убивает добычу не ядом, а удушением, сжимая кольцами тела. Самки заметно крупнее самцов — редкая для змей особенность, выраженная особенно сильно.","fact":"Глаза и ноздри анаконды расположены сверху головы, так что она дышит и следит за добычей, почти целиком скрывшись под водой.","wiki_en":"Green anaconda"},{"name":"Аксолотль","emoji":"🐸","meta":["земноводное","озёра Мексики","сохраняет личиночные черты всю жизнь"],"description":"Мексиканское земноводное, которое в норме не проходит полный метаморфоз и всю жизнь сохраняет наружные перистые жабры и водный образ жизни. Известен исключительной способностью восстанавливать утраченные конечности, хвост и даже части внутренних органов. В дикой природе сохранился лишь в каналах Сочимилько на окраине Мехико и находится на грани исчезновения.","fact":"В аквариумах и лабораториях аксолотлей сейчас намного больше, чем осталось в природе.","wiki_en":"Axolotl"},{"name":"Императорский пингвин","emoji":"🐧","meta":["птица","побережье Антарктиды","крупнейший из пингвинов"],"description":"Самый крупный из ныне живущих пингвинов, единственный, кто размножается в разгар антарктической зимы при экстремальных морозах и ветрах. Самец несколько месяцев без перерыва высиживает единственное яйцо на лапах, укрывая его складкой кожи, пока самка кормится в море. Птицы собираются в плотные группы, по очереди сменяя друг друга на самых холодных внешних позициях.","fact":"Самец императорского пингвина высиживает яйцо на лапах около двух месяцев без еды, в разгар полярной зимы.","wiki_en":"Emperor penguin"},{"name":"Фламинго","emoji":"🦩","meta":["птица","солёные озёра и лагуны","розовый цвет из-за пищи"],"description":"Крупная длинноногая птица, чья розовая окраска появляется не от рождения, а благодаря пигментам из рачков и водорослей, которыми она питается. Фламинго умеет подолгу стоять на одной ноге, экономя тепло тела, а кормится, процеживая воду и ил изогнутым клювом вверх ногами. Живёт большими шумными колониями на солёных озёрах и лагунах.","fact":"Птенцы фламинго рождаются серыми и приобретают розовый цвет только по мере накопления пигментов из пищи.","wiki_en":"Flamingo"},{"name":"Павлин","emoji":"🦚","meta":["птица","леса и сады Южной Азии","роскошный хвост самца"],"description":"Птица, знаменитая огромным веером из перьев самца, украшенным характерными «глазками», которые распускаются во время брачных демонстраций. Вопреки распространённому заблуждению, этот роскошный «хвост» — не хвостовые перья, а сильно удлинённые надхвостные. Самки павлина окрашены гораздо скромнее и выбирают партнёра по качеству его демонстрации.","fact":"Потряхивая раскрытым веером, павлин издаёт инфразвук, которого человеческое ухо не слышит.","wiki_en":"Peafowl"},{"name":"Тукан","emoji":"🐦","meta":["птица","леса Центральной и Южной Америки","огромный яркий клюв"],"description":"Птица тропических лесов Америки с непропорционально большим ярким клювом, который при этом на удивление лёгкий благодаря губчатой внутренней структуре. Клюв помогает дотягиваться до плодов на тонких ветках и служит сигналом статуса и терморегуляции. Туканы гнездятся в дуплах и часто селятся семейными группами.","fact":"Спать тукан устраивается в дупле, закидывая хвост на спину и убирая огромный клюв под крыло.","wiki_en":"Toucan"},{"name":"Ара","emoji":"🦜","meta":["птица","тропические леса Южной Америки","крупный яркий попугай"],"description":"Крупный яркий попугай тропических лесов Южной Америки, способный доживать до глубокой старости и образующий пары на всю жизнь. Мощный изогнутый клюв легко раскалывает твёрдые орехи и семена, недоступные другим птицам. Ара — один из самых узнаваемых символов тропических лесов, но многие виды сильно пострадали от вырубки лесов и отлова.","fact":"На голых участках кожи вокруг глаз у ара проходят тонкие линии перьев, и у каждой птицы этот рисунок свой.","wiki_en":"Macaw"},{"name":"Колибри","emoji":"🌺","meta":["птица","Северная и Южная Америка","самая маленькая птица"],"description":"Крошечная птица Нового Света, способная зависать на месте в воздухе, махая крыльями десятки раз в секунду, и даже летать задом наперёд. Из-за огромных энергозатрат колибри питается почти постоянно, высасывая цветочный нектар длинным клювом. Ночью, чтобы не погибнуть от голода, некоторые виды впадают в состояние, похожее на оцепенение.","fact":"Сердце колибри во время полёта может биться более тысячи раз в минуту.","wiki_en":"Hummingbird"},{"name":"Белоголовый орлан","emoji":"🦅","meta":["птица","Северная Америка","национальный символ США"],"description":"Крупная хищная птица, ставшая национальным символом США благодаря величественному облику и белоснежной голове взрослых особей, которая появляется лишь через несколько лет после рождения. Гнездится у крупных водоёмов и питается в основном рыбой, которую высматривает с большой высоты. Гнёзда белоголового орлана — одни из крупнейших видов птичьих построек, используемых из года в год.","fact":"Белоголовый орлан нередко отбирает добычу у других птиц — за это Бенджамин Франклин в письме назвал его птицей дурного нрава.","wiki_en":"Bald eagle"},{"name":"Полярная сова","emoji":"🦉","meta":["птица","арктическая тундра","охотится и днём, и ночью"],"description":"Крупная сова арктической тундры с густым белым оперением, маскирующим её на фоне снега, — у самцов оно почти полностью белое, у самок с тёмными пестринами. В отличие от большинства сов, охотится и днём, и ночью, приспособившись к полярному дню и ночи. Основу рациона составляют лемминги, и численность популяции сильно зависит от их количества.","fact":"Гнездится полярная сова прямо на земле, устраивая ямку на сухом бугре открытой тундры.","wiki_en":"Snowy owl"},{"name":"Страус","emoji":"🏃","meta":["птица","саванны Африки","крупнейшая и самая быстробегающая птица"],"description":"Крупнейшая из ныне живущих птиц, утратившая способность летать, но взамен ставшая самой быстрой бегающей птицей на планете. Длинные сильные ноги позволяют развивать высокую скорость и наносить мощные удары, способные отпугнуть хищника. Страусы откладывают самые крупные яйца среди всех современных птиц.","fact":"Вопреки известному мифу, страус никогда не прячет голову в песок при опасности.","wiki_en":"Common ostrich"},{"name":"Лебедь","emoji":"🦢","meta":["птица","водоёмы Евразии и Северной Америки","образует пары на всю жизнь"],"description":"Крупная водоплавающая птица с длинной гибкой шеей, которая часто образует пару на всю жизнь и совместно с партнёром растит потомство. Несмотря на изящный облик, лебедь способен сильно ударить крылом, защищая гнездо или птенцов. Несколько видов лебедей отличаются окраской оперения и цветом клюва.","fact":"Из-за большого веса лебедю нужна «взлётная полоса»: он долго разбегается по воде, прежде чем подняться в воздух.","wiki_en":"Swan"},{"name":"Пеликан","emoji":"🐦","meta":["птица","водоёмы по всему миру","огромный горловой мешок"],"description":"Крупная водоплавающая птица с вместительным кожистым мешком под клювом, который служит не для хранения, а для вылавливания рыбы наподобие сачка. Пойманную воду пеликан сцеживает, прежде чем проглотить добычу. Некоторые виды охотятся сообща, сгоняя рыбу к берегу или на мелководье слаженными группами.","fact":"Бурый пеликан добывает рыбу иначе — он бросается за ней в воду с высоты, складывая крылья перед самым ударом.","wiki_en":"Pelican"},{"name":"Белый аист","emoji":"🐦","meta":["птица","Европа, Африка, Западная Азия","символ семьи и деторождения"],"description":"Крупная перелётная птица с характерным чёрно-белым оперением и длинным красным клювом, гнездящаяся на крышах домов, столбах и деревьях вблизи человека. В Европе издавна считается символом семьи и появления детей, отсюда известная легенда о том, что аист приносит новорождённых. Совершает дальние ежегодные перелёты между Европой и Африкой.","fact":"Голоса у взрослого белого аиста почти нет — он «переговаривается» с партнёром громким щёлканьем клюва.","wiki_en":"White stork"},{"name":"Тупик","emoji":"🐧","meta":["птица","берега северной Атлантики","яркий разноцветный клюв"],"description":"Небольшая морская птица с ярким треугольным клювом, окрашивающимся в насыщенные цвета лишь на период размножения, а затем частично линяющим. Тупик отлично плавает и ныряет за рыбой, используя крылья как вёсла под водой, но при этом неуклюже летает и садится. Гнездится колониями в норах на прибрежных скалах и островах.","fact":"Тупик приносит птенцу сразу целый «букет» рыбок, удерживая их в клюве поперёк, иногда около десятка за раз.","wiki_en":"Atlantic puffin"},{"name":"Киви (птица)","emoji":"🥝","meta":["птица","Новая Зеландия","ноздри на конце клюва"],"description":"Нелетающая птица Новой Зеландии размером примерно с курицу, ведущая ночной образ жизни и обладающая необычно острым для птиц обонянием. Это единственная птица, чьи ноздри расположены на самом конце длинного клюва, что помогает находить червей и насекомых в почве по запаху. Киви — национальный символ Новой Зеландии, давший неофициальное прозвище её жителям.","fact":"Относительно размеров тела киви откладывает одно из самых крупных яиц среди всех птиц.","wiki_en":"Kiwi (bird)"},{"name":"Бабочка монарх","emoji":"🦋","meta":["насекомое","Северная и Центральная Америка","совершает дальние миграции"],"description":"Крупная яркая бабочка, знаменитая одной из самых протяжённых миграций среди насекомых: на зимовку в Мексику она летит за тысячи километров. Гусеницы монарха питаются только ваточником, ядовитым для многих животных, что делает несъедобными и самих бабочек. Яркая оранжево-чёрная окраска служит предупреждением для хищников.","fact":"Путь миграции бабочки-монарха в Мексику и обратно занимает несколько поколений — ни одна особь не пролетает его целиком.","wiki_en":"Monarch butterfly"},{"name":"Медоносная пчела","emoji":"🐝","meta":["насекомое","по всему миру, кроме Антарктиды","опыляет растения, даёт мёд"],"description":"Общественное насекомое, живущее крупными семьями с чёткой ролью каждой особи — рабочих, трутней и одной плодовитой матки. Пчёлы сообщают друг другу о найденных цветках особым «танцем», кодирующим направление и расстояние до источника нектара. Опыляя растения, медоносная пчела играет огромную роль в сельском хозяйстве всей планеты.","fact":"Матка живёт несколько лет, а рабочая пчела летом изнашивается за считаные недели работы в поле.","wiki_en":"Western honey bee"},{"name":"Божья коровка","emoji":"🐞","meta":["насекомое","по всему миру","яркая окраска предупреждает хищников"],"description":"Небольшой яркий жук, чья пятнистая окраска предупреждает хищников о неприятном вкусе и способности выделять едкую жидкость из сочленений лапок при угрозе. Большинство видов божьей коровки — активные хищники, поедающие за жизнь тысячи тлей, за что их ценят садоводы и фермеры. Число пятен на надкрыльях зависит от вида, а не от возраста жука.","fact":"Зимуют божьи коровки скоплениями, набиваясь под кору и в щели иногда сотнями особей сразу.","wiki_en":"Coccinellidae"},{"name":"Богомол","emoji":"🙏","meta":["насекомое","тёплые регионы по всему миру","характерная молитвенная поза"],"description":"Хищное насекомое, получившее название за характерную позу передних хватательных лап, будто сложенных для молитвы. На деле эти лапы — молниеносное оружие, которым богомол хватает добычу за доли секунды. Голова богомола способна поворачиваться почти на 180 градусов, что редкость среди насекомых.","fact":"У богомола есть единственное «ухо» на груди, чувствительное к ультразвуку летучих мышей — главных его врагов в темноте.","wiki_en":"Mantis"},{"name":"Сибирский хаски","emoji":"🐶","meta":["млекопитающее (порода собак)","выведена на северо-востоке Азии","ездовая, густая шерсть"],"description":"Ездовая порода собак, выведенная народом чукчей для быстрой и выносливой упряжной езды на большие расстояния по снегу. Густая двойная шерсть и голубые, карие или разноцветные глаза — визитная карточка породы. Хаски отличаются высокой энергичностью и потребностью в постоянных физических нагрузках.","fact":"Хаски почти не лают: вместо лая они завывают и «разговаривают» протяжными ворчащими звуками.","wiki_en":"Siberian Husky"},{"name":"Вельш-корги","emoji":"🐕","meta":["млекопитающее (порода собак)","выведена в Уэльсе","короткие лапы, длинное тело"],"description":"Небольшая пастушья порода собак из Уэльса с характерными короткими лапами и удлинённым телом, изначально выведенная для перегона крупного скота. Корги кусали коров за пятки и ловко уворачивались от ударов копыт благодаря низкому росту. Порода приобрела мировую известность отчасти благодаря любви к ней британской королевы Елизаветы II.","fact":"Корги бывают двух разных пород: пемброки с очень коротким хвостом и кардиганы с длинным пушистым хвостом.","wiki_en":"Pembroke Welsh Corgi"},{"name":"Золотистый ретривер","emoji":"🦮","meta":["млекопитающее (порода собак)","выведена в Шотландии","дружелюбная порода-компаньон"],"description":"Порода собак, выведенная в Шотландии в XIX веке для подачи битой дичи на охоте, отсюда и «мягкая пасть», способная удерживать добычу, не повреждая её. Золотистый ретривер славится дружелюбным, терпеливым характером, из-за чего часто становится собакой-поводырём и семейным компаньоном. Густая золотистая шерсть требует регулярного ухода.","fact":"Породу вывел шотландский лорд Твидмут, скрещивая ретриверов с ныне исчезнувшим твид-уотер-спаниелем.","wiki_en":"Golden Retriever"},{"name":"Немецкая овчарка","emoji":"🐕‍🦺","meta":["млекопитающее (порода собак)","выведена в Германии","служебная и рабочая порода"],"description":"Одна из самых распространённых служебных пород в мире, выведенная в Германии в конце XIX века для пастушьей работы, а позже освоившая полицейскую, военную и спасательную службу. Отличается высоким интеллектом, обучаемостью и преданностью хозяину. Благодаря универсальности немецкую овчарку часто снимают в кино и используют как собаку-поводыря.","fact":"Стандарт породы в конце XIX века задал немецкий офицер Макс фон Штефаниц, начав разведение от одного кобеля по имени Хоранд.","wiki_en":"German Shepherd"},{"name":"Мейн-кун","emoji":"🐈","meta":["млекопитающее (порода кошек)","выведена в США (штат Мэн)","одна из крупнейших пород кошек"],"description":"Одна из крупнейших пород домашних кошек, происходящая из американского штата Мэн, где густая шерсть и крупные лапы помогали переносить суровые зимы. Кисточки на ушах и пушистый хвост внешне напоминают рысь. Несмотря на внушительные размеры, мейн-кун славится мягким, дружелюбным характером и негромким, почти «щебечущим» голосом.","fact":"Мейн-кун официально признан кошкой-символом штата Мэн, откуда порода и происходит.","wiki_en":"Maine Coon"},{"name":"Сфинкс (кошка)","emoji":"🙀","meta":["млекопитающее (порода кошек)","выведена в Канаде","практически без шерсти"],"description":"Порода кошек, отличающаяся почти полным отсутствием шерсти, хотя кожа часто покрыта едва заметным пушком, напоминающим замшу на ощупь. Из-за отсутствия шёрстного покрова сфинкс мёрзнет и любит тепло, а кожа быстро пачкается, требуя частого купания. Порода выведена в Канаде во второй половине XX века на основе природной мутации.","fact":"Гипоаллергенной эту породу считают напрасно: аллергию вызывают белки в слюне и на коже кошки, а не сама шерсть.","wiki_en":"Sphynx cat"}];
